mapper.select:
SELECT s.id AS student_id, s.name AS student_name, s.age AS age, c.id AS course_id, c.name AS course_name, sc.score FROM student s INNER JOIN sc ON s.id = sc.student_id INNER JOIN course c ON sc.course_id = c.id
AND s.id = #{studentId}
AND s.name LIKE CONCAT('%', #{name}, '%')
AND s.age = #{age}
ORDER BY s.id, c.id
